  ('00000000-0000-0000-0000-0000000000b1', 'riyadh-season-launch', '{"en":"Riyadh Season Launch","ar":"إطلاق موسم الرياض"}'::jsonb, '{"en":"A full-funnel campaign — brand film, motion graphics, and always-on social.","ar":"حملة متكاملة — فيلم للعلامة، وموشن جرافيك، وحضور دائم على وسائل التواصل."}'::jsonb, 'draft', true, 1),
