  ('00000000-0000-0000-0000-0000000000b1', 'arabic-first-brand-systems', '{"en":"Arabic-first brand systems","ar":"أنظمة هوية تبدأ بالعربية"}'::jsonb, '{"en":"Why designing the Arabic wordmark first makes the Latin one better.","ar":"لماذا يبدأ تصميم الشعار بالعربية أولًا يحسّن النسخة اللاتينية."}'::jsonb, '{"en":"<p>Designing Arabic-first forces clarity in the letterforms that Latin then inherits.</p>","ar":"<p>التصميم بالعربية أولًا يفرض وضوحًا في الأحرف ترثه اللاتينية لاحقًا.</p>"}'::jsonb, (select id from public.team_members where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'lead-creative'), (select id from public.categories where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'insights'), 'draft', '2026-06-10T09:00:00Z', 4),
  ('00000000-0000-0000-0000-0000000000b1', 'getting-cited-by-ai-answer-engines', '{"en":"Getting cited by AI answer engines","ar":"أن تُذكر في محركات الإجابة بالذكاء الاصطناعي"}'::jsonb, '{"en":"Answer-first structure, named stats, and real authorship win citations.","ar":"البنية القائمة على الإجابة، والإحصاءات المسماة، والتأليف الحقيقي تكسب الاستشهادات."}'::jsonb, '{"en":"<p>Answer-engine visibility rewards answer-first paragraphs and named, verifiable authors.</p>","ar":"<p>ظهورك في محركات الإجابة يكافئ الفقرات التي تبدأ بالإجابة والمؤلفين المعروفين الموثوقين.</p>"}'::jsonb, (select id from public.team_members where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'head-of-growth'), (select id from public.categories where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'insights'), 'draft', '2026-06-14T09:00:00Z', 5)
